//! Bounded, opt-in inventory. Slot changes are atomic when a pickup cannot fit.
use serde::{Serialize,Deserialize};
use std::{collections::{BTreeSet,BTreeMap},path::Path};
use uuid::Uuid;
#[derive(Clone,Debug,PartialEq,Eq,Serialize,Deserialize)]
pub struct ItemStack{pub item:String,pub count:u32}
impl Default for ItemStack{fn default()->Self{Self{item:"Item".into(),count:1}}}
impl ItemStack{pub fn valid(&self)->bool{!self.item.trim().is_empty()&&self.item.len()<=128&&self.count>0&&self.count<=99}}
#[derive(Clone,Debug,PartialEq,Eq,Serialize,Deserialize)]
#[serde(default)]
pub struct Inventory{pub slots:Vec<Option<ItemStack>>,pub collected:BTreeSet<Uuid>,pub equipped:BTreeMap<String,ItemStack>}
impl Default for Inventory{fn default()->Self{Self{slots:vec![None;12],collected:BTreeSet::new(),equipped:BTreeMap::new()}}}
impl Inventory{
 pub fn valid(&self)->bool{(1..=64).contains(&self.slots.len())&&self.collected.len()<=10000&&self.slots.iter().flatten().all(ItemStack::valid)&&self.equipped.len()<=8&&self.equipped.iter().all(|(k,v)|valid_equip_slot(k)&&v.valid()&&v.count==1)}
 pub fn add(&mut self,item:&ItemStack)->bool{if !self.valid()||!item.valid(){return false;}let mut next=self.slots.clone();let mut left=item.count;for stack in next.iter_mut().flatten().filter(|s|s.item==item.item){let n=(99-stack.count).min(left);stack.count+=n;left-=n;}for slot in &mut next{if left==0{break;}if slot.is_none(){*slot=Some(ItemStack{item:item.item.clone(),count:left.min(99)});left-=left.min(99);}}if left>0{return false;}self.slots=next;true}
 pub fn move_slot(&mut self,from:usize,to:usize)->bool{if !self.valid()||from==to||from>=self.slots.len()||to>=self.slots.len(){return false;}let Some(a)=self.slots[from].clone()else{return false;};if let Some(b)=self.slots[to].as_mut(){if b.item==a.item{let n=(99-b.count).min(a.count);if n==0{return false;}b.count+=n;self.slots[from]=(a.count>n).then(||ItemStack{item:a.item,count:a.count-n});return true;}}self.slots.swap(from,to);true}
 pub fn save(&self,path:&Path)->Result<(),String>{if !self.valid(){return Err("Invalid inventory".into());}let data=serde_json::to_vec_pretty(self).map_err(|e|e.to_string())?;let tmp=path.with_extension("json.tmp");std::fs::write(&tmp,data).map_err(|e|e.to_string())?;std::fs::rename(tmp,path).map_err(|e|e.to_string())}
 pub fn load(path:&Path)->Result<Self,String>{let file=std::fs::File::open(path).map_err(|e|e.to_string())?;use std::io::Read;let mut buf=Vec::new();file.take(2*1024*1024+1).read_to_end(&mut buf).map_err(|e|e.to_string())?;if buf.len()>2*1024*1024{return Err("Inventory file too large".into());}let v:Self=serde_json::from_slice(&buf).map_err(|e|e.to_string())?;if v.valid(){Ok(v)}else{Err("Invalid inventory save".into())}}
 /// Only collect independent, leaf pickup objects; avoid orphaning scene descendants.
 pub fn collect_nearby(&mut self,p:&mut crate::Project)->Result<String,String>{let pos=p.objects.iter().find(|o|o.player).ok_or("No player")?.position;let parents:BTreeSet<_>=p.objects.iter().filter_map(|o|o.parent).collect();let target=p.objects.iter().filter(|o|!o.player&&!o.camera&&o.pro.pickup.is_some()&&!self.collected.contains(&o.id)&&!parents.contains(&o.id)).filter_map(|o|{let d=(o.position[0]-pos[0]).hypot(o.position[1]-pos[1]);(d<=80.).then_some((o.id,d,o.pro.pickup.as_ref().unwrap().clone()))}).min_by(|a,b|a.1.total_cmp(&b.1));let Some((id,_,item))=target else{return Err("No pickup within 80 px".into());};if self.collected.len()>=10000||!self.add(&item){return Err("Inventory full or invalid item".into());}self.collected.insert(id);p.objects.retain(|o|o.id!=id);Ok(format!("Collected {} × {}",item.item,item.count))}
 pub fn remove_collected(&self,p:&mut crate::Project){let parents:BTreeSet<_>=p.objects.iter().filter_map(|o|o.parent).collect();p.objects.retain(|o|o.player||o.camera||parents.contains(&o.id)||o.pro.pickup.is_none()||!self.collected.contains(&o.id));}
}
#[cfg(test)]mod tests{use super::*;#[test]fn full_is_atomic(){let mut i=Inventory{slots:vec![Some(ItemStack{item:"A".into(),count:98})],..Default::default()};let before=i.clone();assert!(!i.add(&ItemStack{item:"A".into(),count:2}));assert_eq!(i,before);assert!(i.add(&ItemStack{item:"A".into(),count:1}));}
#[test]fn merge_and_swap(){let mut i=Inventory{slots:vec![Some(ItemStack{item:"A".into(),count:70}),Some(ItemStack{item:"A".into(),count:50}),None],..Default::default()};assert!(i.move_slot(0,1));assert_eq!(i.slots[1].as_ref().unwrap().count,99);assert_eq!(i.slots[0].as_ref().unwrap().count,21);assert!(i.move_slot(0,2));assert!(i.slots[0].is_none());}
#[test]fn pickup_and_save(){let mut p=crate::Project::default();let mut o=crate::Object::new("pickup",[5.,0.],[8.;2],[255;4]);o.pro.pickup=Some(ItemStack::default());let id=o.id;p.objects.push(o);let mut inv=Inventory::default();assert!(inv.collect_nearby(&mut p).is_ok());assert!(inv.collected.contains(&id));assert!(!p.objects.iter().any(|o|o.id==id));let path=std::env::temp_dir().join(format!("forge-inv-{}.json",Uuid::new_v4()));inv.save(&path).unwrap();assert_eq!(Inventory::load(&path).unwrap(),inv);std::fs::remove_file(path).unwrap();}}

#[cfg(test)]mod fixture_test{#[test]fn inventory_scene(){let path=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("examples/inventory/project.forge.json");let mut p=crate::Project::load(&path).unwrap();let mut inv=p.settings.inventory.clone().unwrap();assert!(inv.collect_nearby(&mut p).is_ok());assert_eq!(inv.slots[0].as_ref().unwrap().count,5);assert_eq!(p.objects.iter().filter(|o|o.pro.pickup.is_some()).count(),2);}}

/// Explicit per-project definitions. Missing definitions remain ordinary collectible items.
#[derive(Clone,Debug,Default,PartialEq,Serialize,Deserialize)]
#[serde(default)]
pub struct ItemDefinition {pub equip_slot:String,pub heal:f32,pub damage_bonus:f32,pub variable:String,pub variable_delta:f32}
fn valid_equip_slot(s:&str)->bool{matches!(s,"weapon"|"armor"|"accessory"|"head"|"offhand")}
impl ItemDefinition {pub fn valid(&self)->bool{(self.equip_slot.is_empty()||valid_equip_slot(&self.equip_slot))&&self.heal.is_finite()&&(0. ..=1000.).contains(&self.heal)&&self.damage_bonus.is_finite()&&(0. ..=1000.).contains(&self.damage_bonus)&&self.variable.len()<=128&&self.variable_delta.is_finite()&&self.variable_delta.abs()<=10000.&&(self.variable_delta==0.||!self.variable.trim().is_empty())&&!self.variable.starts_with("forge_")}}
impl Inventory {
 fn take_one(&mut self,index:usize)->Result<ItemStack,String>{let slot=self.slots.get_mut(index).ok_or("Invalid slot")?;let stack=slot.as_mut().ok_or("Empty slot")?;if !stack.valid(){return Err("Invalid stack".into());}let item=ItemStack{item:stack.item.clone(),count:1};stack.count-=1;if stack.count==0{*slot=None;}Ok(item)}
 pub fn equipment_valid(&self,catalog:&BTreeMap<String,ItemDefinition>)->bool{self.valid()&&self.equipped.iter().all(|(slot,item)|catalog.get(&item.item).is_some_and(|d|d.valid()&&d.equip_slot==*slot))}
 pub fn damage_bonus(&self,catalog:&BTreeMap<String,ItemDefinition>)->f32{self.equipped.iter().filter_map(|(slot,item)|catalog.get(&item.item).filter(|d|d.valid()&&d.equip_slot==*slot)).map(|d|d.damage_bonus).sum::<f32>().min(1000.)}
 pub fn equip(&mut self,index:usize,catalog:&BTreeMap<String,ItemDefinition>)->Result<String,String>{if !self.equipment_valid(catalog){return Err("Invalid equipment".into());}let mut next=self.clone();let item=next.take_one(index)?;let def=catalog.get(&item.item).filter(|d|d.valid()&&!d.equip_slot.is_empty()).ok_or("Item cannot be equipped")?;if let Some(old)=next.equipped.remove(&def.equip_slot){if !next.add(&old){return Err("No space for previous equipment".into());}}let name=item.item.clone();next.equipped.insert(def.equip_slot.clone(),item);*self=next;Ok(format!("Equipped {name}"))}
 pub fn unequip(&mut self,slot:&str)->Result<String,String>{let mut next=self.clone();let item=next.equipped.remove(slot).ok_or("Empty equipment slot")?;if !next.add(&item){return Err("Inventory full".into());}*self=next;Ok(format!("Unequipped {}",item.item))}
 pub fn use_item(&mut self,index:usize,p:&mut crate::Project)->Result<String,String>{if !self.valid(){return Err("Invalid inventory".into());}let item=self.slots.get(index).and_then(Option::as_ref).ok_or("Empty slot")?;let def=p.settings.item_catalog.get(&item.item).filter(|d|d.valid()).cloned().ok_or("No item effect")?;let player=p.objects.iter_mut().find(|o|o.player).ok_or("No player")?;let heal=player.pro.combat.as_ref().filter(|c|c.health>0.&&c.health<c.max_health&&c.max_health.is_finite()).map(|c|def.heal.min(c.max_health-c.health)).unwrap_or(0.);let delta=if def.variable_delta!=0.{let prev=player.pro.variables.get(&def.variable).copied().unwrap_or(0.);let value=prev+def.variable_delta;if !value.is_finite(){return Err("Invalid variable value".into());}Some(value)}else{None};if heal<=0.&&delta.is_none(){return Err("No applicable effect".into());}let consumed=self.take_one(index)?;if heal>0.{if let Some(c)=player.pro.combat.as_mut(){c.health+=heal;}}if let Some(v)=delta{player.pro.variables.insert(def.variable,v);}Ok(format!("Used {}",consumed.item))}
}
#[cfg(test)]mod pro_tests{use super::*;#[test]fn equip_swap_and_bonus(){let mut i=Inventory::default();let mut c=BTreeMap::new();c.insert("Sword".into(),ItemDefinition{equip_slot:"weapon".into(),damage_bonus:2.,..Default::default()});assert!(i.add(&ItemStack{item:"Sword".into(),count:1}));i.equip(0,&c).unwrap();assert_eq!(i.damage_bonus(&c),2.);assert!(i.slots[0].is_none());i.unequip("weapon").unwrap();assert_eq!(i.damage_bonus(&c),0.);assert_eq!(i.slots[0].as_ref().unwrap().item,"Sword");}#[test]fn use_heal_only_if_effect(){let mut p=crate::Project::default();p.settings.item_catalog.insert("Medkit".into(),ItemDefinition{heal:2.,..Default::default()});let actor=p.objects.iter_mut().find(|o|o.player).unwrap();actor.pro.combat=Some(crate::combat::Combat{health:2.,max_health:5.,..Default::default()});let mut i=Inventory::default();i.add(&ItemStack{item:"Medkit".into(),count:2});i.use_item(0,&mut p).unwrap();assert_eq!(p.objects.iter().find(|o|o.player).unwrap().pro.combat.as_ref().unwrap().health,4.);assert_eq!(i.slots[0].as_ref().unwrap().count,1);i.use_item(0,&mut p).unwrap();assert!(i.slots[0].is_none());}}
